item.content:encoded:
/* single column review hero */
@media (min-width: 576px) {
	.postid-23 .review-hero {
		flex-direction: column;
	}
	.postid-23 .review-hero > div:first-of-type {
		margin-bottom: 2rem;
	}	
}

/* site title gradient */
.site-title a {
	font-size: 2rem;
	font-weight: 700;
	line-height: 1;
	background-image: linear-gradient(64deg, var(--color-akurai-font-main), var(--color-akurai-primary));
	-webkit-background-clip: text;
	-webkit-text-fill-color: transparent;
}

/* bonuses menu item label */
a[href="#bonuses"]:after {
  content: 'NEW';
  position: relative;
	top: -2px;
	margin-left: 3px;
	padding: 2px 3px;
  font-size: 11px;
	color: #fff;
  background: red;
	border-radius: 3px;
}
